model.component("comp1").physics().create("nipfl", "NonisothermalPipeFlow", "geom1");
model.component("comp1").physics("nipfl").feature("pipe1").set("shape", "Round");
model.component("comp1").physics("nipfl").feature("pipe1").set("innerd", "25[mm]");
model.study().create("std1");
model.study("std1").create("stat", "Stationary");
// Application Library: Pipe_Flow_Module/Heat_Transfer/borehole_heat_exchanger_pipe_flow, pipeline_insulation, mold_cooling

model.component("comp1").physics().create("whtd", "WaterHammer", "geom1");
model.component("comp1").physics("whtd").create("pres1", "Pressure", 0);
model.component("comp1").physics("whtd").feature("pres1").selection().set(new int[]{1});
model.component("comp1").physics("whtd").create("source1", "Source", 0);
model.component("comp1").physics("whtd").feature("source1").selection().set(new int[]{2});
model.study().create("std1");
model.study("std1").create("time", "Transient");
// Application Library: Pipe_Flow_Module/Verification_Examples/water_hammer_verification

model.component("comp1").physics().create("pfl", "FlowInPipes", "geom1");
// GUI: Pipe Flow > Fluid Model = Bingham; Fluid Properties: yield stress tauB = 5[Pa], plastic viscosity muB = 0.05[Pa*s]
// Application Library: Pipe_Flow_Module/Tutorials/slurry_transport

model.component("comp1").physics().create("pfl", "FlowInPipes", "geom1");
model.component("comp1").physics("pfl").feature("pipe1").set("shape", "Round");
model.component("comp1").physics("pfl").feature("pipe1").set("innerd", "50[mm]");
// GUI: Flow Resistance > Friction model: Haaland; Surface roughness: Commercial steel (0.046 mm)

model.component("comp1").physics("whtd").create("source1", "Source", 0);
model.component("comp1").physics("whtd").feature("source1").selection().set(new int[]{2});
